# Case 1: a condition on natural numbers (Example 1)
print("Case 1: {x in N : x < 5}, candidates 0 to 6")
for x in range(7):
    print(f"  {x} < 5: {x < 5}")
A = {x for x in range(7) if x < 5}
print(f"  set {sorted(A)}, size {len(A)}")

# Case 2: negatives pass too (Example 3)
print("Case 2: {x in Z : x^2 < 10}, candidates -4 to 4, since x^2 >= 16 beyond")
for x in range(-4, 5):
    print(f"  ({x})^2 = {x * x} < 10: {x * x < 10}")
C = {x for x in range(-4, 5) if x * x < 10}
print(f"  set {sorted(C)}, size {len(C)}")

# Case 3: a rule, where repeats collapse (Example 4)
print("Case 3: {k^2 : k from -2 to 2}")
for k in range(-2, 3):
    print(f"  k = {k} gives {k * k}")
D = {k * k for k in range(-2, 3)}
print(f"  set {sorted(D)}, size {len(D)}")

# Case 4: nothing passes (Example 5)
print("Case 4: {x in Z : x^2 = -1}, candidates -3 to 3")
E = {x for x in range(-3, 4) if x * x == -1}
print(f"  no square is negative, so the set is {sorted(E)}, size {len(E)}")

