def check(A, B):
    print(f"Is {sorted(A)} a subset of {sorted(B)}?")
    missing = {x for x in A if x not in B}
    for x in sorted(A):
        print(f"  {x} in B: {x in B}")
    if len(A) == 0:
        print("  no elements to check, so it is vacuously true")
    print(f"  missing from B: {sorted(missing)}")
    print(f"  subset: {len(missing) == 0}, proper: {len(missing) == 0 and A != B}")


check({2, 4}, {1, 2, 3, 4})
check({2, 5}, {1, 2, 3, 4})
check(set(), {7})
check({1, 2, 3}, {3, 2, 1})

print("Power set of {1, 2, 3}, one element at a time:")
subsets = [set()]
print(f"  start: {len(subsets)} subset")
for x in [1, 2, 3]:
    bigger = []
    for S in subsets:
        bigger.append(S)
    for S in subsets:
        bigger.append(S | {x})
    subsets = bigger
    print(f"  bring in {x}: {len(subsets)} subsets")
for S in subsets:
    print("  ", sorted(S))
